head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > visibleWeekNum]<br/>Calendar 컴포넌트의 가운데 날짜 영역에 표시될 주(Week)의 갯수를 설정합니다.",
    "validation" : [
        "Number 타입으로 Calendar 컴포넌트의 가운데 날짜 영역에 표시될 주(Week)의 갯수를 설정합니다.",
        "설정된 값에 맞게 컴포넌트의 높이가 조정됩니다. (주 갯수에 비례)",
        "값을 설정하지 않으면 기본값 6 으로 설정됩니다.",
        "calendarValueType=yearMonth 이면 날짜 영역이 표시되지 않으므로 visibleWeekNum 효과가 적용되지 않습니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        visibleWeekNum : con_visibleWeekNum.getText(),
        calendarValueType : con_calendarValueType.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// 날짜 영역 주(Week) 행 갯수 / target1.options.visibleWeekNum
scwin.getWeekRowInfo = function () {
    let calendarRender = target1.render;
    let contentTable = calendarRender.querySelector('table.w2calendar_content_table');
    let weekRows = contentTable ? contentTable.querySelectorAll('tbody tr') : [];

    // validation: 적용된 visibleWeekNum 값 (미설정 시 기본값 6)
    wf_body_bottom.getObj("scwin").setReturnValue("[visibleWeekNum 옵션값] target1.options.visibleWeekNum = " + target1.options.visibleWeekNum);
    // validation: 날짜 영역에 표시된 주(Week) 행 갯수 = visibleWeekNum 값
    wf_body_bottom.getObj("scwin").setReturnValue("[날짜 영역 주(Week) 행 갯수] tbody tr 갯수 = " + weekRows.length + "개");
}



// Calendar 컴포넌트 높이 (주 갯수에 비례)
scwin.getHeightInfo = function () {
    let calendarRender = target1.render;
    let height = calendarRender.offsetHeight;

    // validation: 설정된 값에 맞게 컴포넌트의 높이가 조정됨
    wf_body_bottom.getObj("scwin").setReturnValue("[Calendar 컴포넌트 높이] target1.render.offsetHeight = " + height + "px");
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getWeekRowInfo();
    scwin.getHeightInfo();
}



scwin.target1_onclick = function (e) {
    setTimeout(() => {
        scwin.getWeekRowInfo();
        scwin.getHeightInfo();
    }, 100);
}
